'use strict';

function money(cents, currency) {
  if (!Number.isInteger(cents)) throw new TypeError('cents must be an integer');
  var sign = cents < 0 ? '-' : '';
  var abs = Math.abs(cents);
  var frac = String(abs % 100);
  while (frac.length < 2) frac = '0' + frac;
  return sign + (currency || 'USD') + ' ' + Math.floor(abs / 100) + '.' + frac;
}

function pct(ratio) {
  if (typeof ratio !== 'number') throw new TypeError('ratio must be a number');
  return (Math.round(ratio * 1000) / 10) + '%';
}

module.exports = { money: money, pct: pct, VERSION: '1.4.0' };
